// One output item per inbound text message from someone on the roster.
//
// Deterministic parse first, model second. A bare number, "all" or "none"
// covers almost every reply and costs nothing; only the tail — "did 6, two
// no-shows" — reaches the LLM branch. Putting the cheap path first is also
// what keeps this debuggable: most executions never touch a model at all.
const ZONE = 'Europe/Helsinki';

// A reply typed at 00:30 is about the day that just ended, not the new one.
const DAY_ROLLOVER_HOUR = 4;

const ALL_WORDS = ['all', 'all of them', 'yes', 'yep', 'yup', 'done', 'all done', 'kaikki', 'joo', 'kyllä'];
const NONE_WORDS = ['none', 'no', 'nope', 'zero', '0', 'ei', 'en yhtään'];

// Openers that make a sentence a question even without a question mark.
const QUESTION_WORDS = [
  'what', 'whats', 'how', 'why', 'when', 'where', 'which', 'who', 'can', 'could', 'do',
  'does', 'is', 'are', 'should', 'any', 'anyone', 'tell', 'help',
  'mitä', 'mikä', 'miten', 'kuinka', 'miksi', 'milloin', 'missä', 'kuka', 'onko', 'voiko',
  'voinko', 'saako', 'kerro', 'apua',
];

function parse(text, target) {
  const clean = text.trim().toLowerCase();

  if (ALL_WORDS.includes(clean)) return { calls: target, how: 'all' };
  if (NONE_WORDS.includes(clean)) return { calls: 0, how: 'none' };

  // Only trust a bare number when the message is essentially just that number
  // ("6", "6/8", "6 calls"). A longer sentence goes to the model, so that
  // "tomorrow I'll do 8" is not logged as eight calls today.
  if (clean.length <= 12) {
    const match = clean.match(/(?<!\d)(\d{1,3})(?!\d)/);
    if (match) {
      const n = Number(match[1]);
      if (n >= 0 && n <= 100) return { calls: n, how: 'number' };
    }
  }

  return { calls: null, how: 'unparsed' };
}

// Reps ask things as well as report numbers. This only decides where the
// message goes, not what the answer is — and it is checked after the number
// has been looked for, so "did 6, why is the CRM down?" is still logged as six.
function looksLikeQuestion(text) {
  const clean = text.trim().toLowerCase();
  const words = clean.split(/\s+/).filter(Boolean);

  // "?" or "6?" on its own is someone querying their own number, not asking
  // the handbook anything it could match.
  if (words.length < 2) return false;

  if (clean.includes('?')) return true;

  return QUESTION_WORDS.includes(words[0].replace(/[^\p{L}]/gu, ''));
}

// The roster arrives on this node's input; the messages come from the trigger.
const roster = new Map();
for (const item of $input.all()) {
  const phone = String(item.json.phone ?? '').replace(/\D/g, '');
  if (phone) roster.set(phone, item.json);
}

const out = [];

for (const event of $('WhatsApp Trigger').all()) {
  for (const message of event.json.messages ?? []) {
    if (message.type !== 'text') continue;

    const phone = String(message.from ?? '').replace(/\D/g, '');
    const rep = roster.get(phone);

    // Someone not on the roster messaged the business number. Not ours to log.
    if (!rep) continue;

    const text = String(message.text?.body ?? '').trim();
    const target = Number(rep.daily_target) || 8;

    const stamp = Number(message.timestamp);
    const receivedAt = Number.isFinite(stamp) && stamp > 0
      ? DateTime.fromSeconds(stamp).setZone(ZONE)
      : $now.setZone(ZONE);

    const forDay = receivedAt.hour < DAY_ROLLOVER_HOUR
      ? receivedAt.minus({ days: 1 })
      : receivedAt;

    const dateKey = forDay.toFormat('yyyy-MM-dd');
    const { calls, how } = parse(text, target);

    out.push({
      json: {
        key: `${dateKey}|${phone}`,
        date: dateKey,
        weekday: forDay.toFormat('ccc'),
        name: String(rep.name ?? '').trim() || phone,
        phone,
        target,
        calls: calls === null ? '' : calls,
        status: calls === null ? 'unparsed' : 'answered',
        note: how,
        raw_reply: text,
        logged_at: receivedAt.toISO(),
        parsed: calls !== null,
        looks_like_question: looksLikeQuestion(text),
        message_id: message.id ?? '',
      },
    });
  }
}

return out;

// Every log row in, one row per rep for the current week out.
//
// "asked" and "answered" are counted separately on purpose: a silent day is
// not a zero-call day, and a coach needs to see which one they are looking at.
const ZONE = 'Europe/Helsinki';

const now = $now.setZone(ZONE);
const weekStart = now.startOf('week');
const weekEnd = weekStart.plus({ days: 6 }).endOf('day');
const weekLabel = now.toFormat("kkkk-'W'WW");

const DAY_KEYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];

const byRep = new Map();

for (const item of $input.all()) {
  const row = item.json;

  const date = DateTime.fromFormat(String(row.date ?? ''), 'yyyy-MM-dd', { zone: ZONE });
  if (!date.isValid || date < weekStart || date > weekEnd) continue;

  const phone = String(row.phone ?? '').replace(/\D/g, '');
  if (!phone) continue;

  if (!byRep.has(phone)) {
    byRep.set(phone, {
      name: String(row.name ?? '').trim() || phone,
      phone,
      asked: 0,
      answered: 0,
      calls: 0,
      target_total: 0,
      hit_days: 0,
      days: {},
    });
  }

  const rep = byRep.get(phone);
  const target = Number(row.target) || 0;

  rep.asked += 1;
  rep.target_total += target;

  // An empty cell means the nudge went out and nothing came back.
  const answer = row.calls;
  const calls = answer === '' || answer === null || answer === undefined ? null : Number(answer);

  if (calls !== null && Number.isFinite(calls)) {
    rep.answered += 1;
    rep.calls += calls;
    if (target > 0 && calls >= target) rep.hit_days += 1;
    rep.days[DAY_KEYS[date.weekday - 1]] = calls;
  }
}

return [...byRep.values()]
  .sort((a, b) => b.calls - a.calls || a.name.localeCompare(b.name))
  .map((rep) => ({
    json: {
      id: `${weekLabel}|${rep.phone}`,
      week: weekLabel,
      week_starting: weekStart.toFormat('yyyy-MM-dd'),
      name: rep.name,
      phone: rep.phone,
      mon: rep.days.mon ?? '',
      tue: rep.days.tue ?? '',
      wed: rep.days.wed ?? '',
      thu: rep.days.thu ?? '',
      fri: rep.days.fri ?? '',
      asked: rep.asked,
      answered: rep.answered,
      calls: rep.calls,
      target_total: rep.target_total,
      hit_days: rep.hit_days,
      pct_of_target: rep.target_total > 0 ? Math.round((rep.calls / rep.target_total) * 100) : 0,
    },
  }));

// Weekly rows in, one Chart.js config plus a caption out.
//
// Form: a horizontal progress-to-goal bar, one row per rep — calls made, then
// the remainder of the target as a recessive track. It is the only shape that
// stays readable on a phone as the roster grows, and the bar length answers the
// coach's actual question ("who is short, and by how much") without a second axis.
// The per-day detail is not thrown away: it goes to the Weekly tab, where the
// client can chart it themselves.
const reps = $input.all().map((item) => item.json);
if (reps.length === 0) return [];

const CALLS_MADE = '#2a78d6';  // categorical slot 1
const TO_TARGET = '#cfd0cb';   // a track, not a series — deliberately recessive
const INK = '#52514e';
const INK_STRONG = '#0b0b0b';
const GRID = '#ececea';

const week = reps[0].week;

const chart = {
  type: 'horizontalBar',
  data: {
    // The value rides in the axis label rather than inside the bar: a rep on 0 or
    // 1 calls has no bar to write in, and that is exactly the rep you need to read.
    labels: reps.map((rep) => [rep.name, `${rep.calls} of ${rep.target_total}`]),
    datasets: [
      {
        label: 'Calls made',
        backgroundColor: CALLS_MADE,
        data: reps.map((rep) => rep.calls),
        // A 2px surface-coloured edge reads as a gap between the segments.
        borderColor: '#ffffff',
        borderWidth: 2,
        barPercentage: 0.62,
        categoryPercentage: 0.8,
      },
      {
        label: 'Still to target',
        backgroundColor: TO_TARGET,
        data: reps.map((rep) => Math.max(0, rep.target_total - rep.calls)),
        borderColor: '#ffffff',
        borderWidth: 2,
        barPercentage: 0.62,
        categoryPercentage: 0.8,
      },
    ],
  },
  options: {
    responsive: false,
    defaultFontColor: INK,
    defaultFontSize: 13,
    title: {
      display: true,
      text: `Sales calls vs. weekly target — ${week}`,
      fontColor: INK_STRONG,
      fontSize: 17,
      padding: 16,
    },
    legend: { position: 'bottom', labels: { boxWidth: 12, padding: 16 } },
    // QuickChart auto-registers chartjs-plugin-datalabels, which would print a
    // number inside every segment. The values are already on the axis, and a
    // rep on 0 calls has no segment to print into.
    plugins: { datalabels: { display: false } },
    layout: { padding: { left: 8, right: 24, top: 0, bottom: 8 } },
    scales: {
      xAxes: [{
        stacked: true,
        ticks: { beginAtZero: true, fontColor: INK },
        gridLines: { color: GRID, zeroLineColor: GRID, drawBorder: false },
        scaleLabel: { display: true, labelString: 'Calls', fontColor: INK },
      }],
      yAxes: [{
        stacked: true,
        ticks: { fontColor: INK_STRONG },
        gridLines: { display: false, drawBorder: false },
      }],
    },
  },
};

const lines = reps.map((rep) => {
  const silent = rep.asked - rep.answered;
  const tail = silent > 0 ? `, ${silent} day${silent === 1 ? '' : 's'} silent` : '';
  return `${rep.name}: ${rep.calls}/${rep.target_total} (${rep.pct_of_target}%) · hit target ${rep.hit_days}/${rep.asked} days${tail}`;
});

return [{
  json: {
    week,
    chart,
    height: 150 + reps.length * 58,
    summary: `Sales calls — week ${week}\n\n${lines.join('\n')}`,
  },
}];

// One output item per question a rep asked, carrying the handbook rows that
// might answer it.
//
// Same shape as the reply parser: cheap path first. Word overlap against the
// handbook is free and runs on every question; the model only ever sees the
// three rows that scored, never the whole handbook. That keeps the prompt
// small, keeps the answer anchored to something a human wrote, and means a
// missing Anthropic credential still sends the top row verbatim.
const MAX_CANDIDATES = 3;

// Below this the message is about something the handbook does not cover.
// Two is one keyword hit, or two words shared with a question.
const MIN_SCORE = 2;

const WHATSAPP_LIMIT = 900;

// Words that match everything and therefore mean nothing here.
const STOPWORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'but', 'if', 'of', 'to', 'in', 'on', 'for', 'with', 'about',
  'is', 'are', 'was', 'were', 'be', 'do', 'does', 'did', 'can', 'could', 'should', 'would',
  'i', 'we', 'you', 'they', 'it', 'me', 'my', 'our', 'your', 'what', 'whats', 'how', 'why',
  'when', 'where', 'which', 'who', 'this', 'that', 'there', 'here', 'any', 'some', 'get',
  'ja', 'tai', 'jos', 'on', 'ei', 'se', 'mitä', 'mikä', 'miten', 'kuinka', 'miksi', 'milloin',
  'missä', 'kuka', 'onko', 'voiko', 'voinko', 'saako', 'meidän', 'minun', 'kerro',
]);

function terms(text) {
  return String(text ?? '')
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((word) => word.length > 2 && !STOPWORDS.has(word));
}

// A Notion checkbox arrives as a real boolean; the same column imported from a
// CSV arrives as the word. No column at all means nobody has retired anything.
function isActive(value) {
  if (value === undefined || value === null || value === '') return true;
  if (typeof value === 'boolean') return value;
  return ['true', 'yes', '1', 'x'].includes(String(value).trim().toLowerCase());
}

// The Notion node's simplified output names columns `property_<snake_case>`,
// and the title column comes through as `name` as well.
function row(json) {
  const keywords = Array.isArray(json.property_keywords)
    ? json.property_keywords.map((k) => String(k))
    : String(json.property_keywords ?? '').split(',');

  return {
    question: String(json.property_question ?? json.name ?? '').trim(),
    answer: String(json.property_answer ?? '').trim(),
    keywords: keywords.map((k) => k.trim()).filter(Boolean),
    url: String(json.url ?? ''),
    active: isActive(json.property_active),
  };
}

function score(asked, entry) {
  const wanted = new Set(asked);
  if (!wanted.size) return 0;

  let total = 0;

  // A keyword is a phrasing someone chose on purpose, so it counts double.
  for (const keyword of entry.keywords) {
    for (const word of terms(keyword)) if (wanted.has(word)) total += 2;
  }

  for (const word of new Set(terms(entry.question))) if (wanted.has(word)) total += 1;

  return total;
}

// The handbook arrives on this node's input; the questions come from the parse
// node, the same way that one takes its messages from the trigger. A failed
// Notion call lands here too, as an item with no question on it — scoring it
// finds nothing and every rep gets the no-answer line, which is the point: the
// lane degrades instead of going quiet.
const handbook = $input
  .all()
  .map((item) => row(item.json))
  .filter((entry) => entry.question && entry.answer && entry.active);

const out = [];

for (const item of $('Match rep & parse reply').all()) {
  if (!item.json.looks_like_question) continue;

  const asked = terms(item.json.raw_reply);

  const ranked = handbook
    .map((entry) => ({ ...entry, score: score(asked, entry) }))
    .filter((entry) => entry.score >= MIN_SCORE)
    .sort((a, b) => b.score - a.score)
    .slice(0, MAX_CANDIDATES);

  const best = ranked[0];

  out.push({
    json: {
      phone: item.json.phone,
      name: item.json.name,
      question: item.json.raw_reply,
      matched: Boolean(best),
      // What the model is allowed to answer from, and nothing else.
      handbook: ranked
        .map((entry, i) => `${i + 1}. Q: ${entry.question}\n   A: ${entry.answer}`)
        .join('\n'),
      // What goes out when the model is unavailable or there was no match.
      fallback_answer: best
        ? best.answer.slice(0, WHATSAPP_LIMIT)
        : `I don't have an answer for that in the handbook. Ask your coach, and reply here with your call count whenever you're ready.`,
      source: best ? best.url : '',
      // Appended by the Set node below. Built here because an n8n expression
      // cannot hold the separator without fighting the escaping.
      source_suffix: best && best.url ? ` — ${best.url}` : '',
      matched_question: best ? best.question : '',
      handbook_size: handbook.length,
    },
  });
}

return out;

